// src/calculators/KTBundlingCalculator.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

import KTBundlingForm from './KTBundlingForm';
import TotalCondition from '../components/conditions/TotalCondition';
import GuideCondition from '../components/conditions/GuideCondition';
import HomeCondition from '../components/conditions/HomeCondition';
import PremiumFamilyCondition from '../components/conditions/PremiumFamilyCondition';
import PremiumSingleCondition from '../components/conditions/PremiumSingleCondition';
import SpecialCondition from '../components/conditions/SpecialCondition';
import SmallBizCondition from '../components/conditions/SmallBizCondition';
import BizCondition from '../components/conditions/BizCondition';
import KTBundlingResult from './KTBundlingResult';


const BUNDLE_OPTIONS = [
  { key: 'guide',   label: '결합 안내' },
  { key: 'home',    label: '홈 결합' },
  { key: 'family',  label: '프리미엄 가족 결합' },
  { key: 'premium', label: '프리미엄 싱글 결합' },
  { key: 'total',   label: '총액 결합' },
  { key: 'special', label: '으랏차차 결합' },
  { key: 'smallbiz',label: '소상공인 결합' },
  { key: 'biz',     label: 'Biz 결합' },
];

export default function KTBundlingCalculator() {
  const navigate = useNavigate();
  const [selected, setSelected] = useState(null);
  const [pricingData, setPricingData] = useState(null);
  const [formData, setFormData] = useState({});
  const [result, setResult] = useState(null);

  useEffect(() => {
    if (!selected || selected === 'guide') return;
    fetch(`/api/kt-bundling-pricing?type=${selected}`)
      .then(r => r.json())
      .then(setPricingData)
      .catch(console.error);
  }, [selected]);

  const handleCalculate = () => {
    if (!pricingData || selected !== 'total') return;
    // 계산 로직...
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <main className="container mx-auto px-4 py-6">
        {/* 1) 페이지 헤더 */}
        <h1 className="text-center text-2xl font-bold mb-6">KT 결합 계산기</h1>

        <div className="max-w-3xl mx-auto bg-white rounded-lg shadow overflow-hidden">
          <div className="p-6">

            {/* 2) 메뉴 선택(첫 진입) */}
            {!selected && (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
                  {BUNDLE_OPTIONS.map(opt => (
                    <button
                      key={opt.key}
                      onClick={() => { setSelected(opt.key); setPricingData(null); setResult(null); }}
                      className="bg-white border rounded-lg py-3 shadow-sm hover:bg-gray-50 transition"
                    >{opt.label}</button>
                  ))}
                </div>
                <button
                  onClick={() => navigate('/')}
                  className="w-full bg-white border rounded-lg py-2 shadow-sm hover:bg-gray-50 transition"
                >메인 메뉴로 돌아가기</button>
              </>
            )}

            {/* 3) 개별 계산기 화면 */}
            {selected && selected !== 'guide' && (
              <>
                {/* 3-1) 상단: '총액 결합' 일 때만 나타나는 인터넷/모바일 선택 UI */}
                {selected === 'total' && (
                  <KTBundlingForm
                    formData={formData}
                    setFormData={setFormData}
                    pricingData={pricingData}
                    onCalculate={handleCalculate}
                  />
                )}

                {/* 3-2) 조건표 */}
                <h2 className="text-center font-semibold mb-4">
                  {BUNDLE_OPTIONS.find(o => o.key === selected).label} 할인 계산기
                </h2>
                {selected === 'total' && <TotalCondition />}       {/* 세 번째 스크린샷 표 */}
                {selected === 'home'    && <HomeCondition />}
                {selected === 'family'  && <PremiumFamilyCondition />}
                {selected === 'premium' && <PremiumSingleCondition />}
                {selected === 'special' && <SpecialCondition />}
                {selected === 'smallbiz'&& <SmallBizCondition />}
                {selected === 'biz'     && <BizCondition />}

                {/* 3-3) 결과/버튼 */}
                {selected === 'total' && result && <KTBundlingResult result={result} />}
                <button
                  onClick={() => setSelected(null)}
                  className="mt-6 w-full bg-sky-100 border rounded-lg py-2 shadow-sm hover:bg-sky-200 transition mb-4"
                >결합 메뉴로 돌아가기</button>
                <button
                  onClick={() => navigate('/')}
                  className="w-full bg-white border rounded-lg py-2 shadow-sm hover:bg-gray-50 transition"
                >메인 메뉴로 돌아가기</button>
              </>
            )}

            {/* 4) '결합 안내' 탭 */}
            {selected === 'guide' && <GuideCondition />}
          </div>
        </div>
      </main>
    </div>
  );
}
