// src/calculators/KTBundlingForm.jsx
import React from 'react';

export default function KTBundlingForm({
  selected,        // 'total' 혹은 다른 결합 종류
  formData,
  setFormData,
  pricingData,     // 서버에서 받아오는 { internet: {...}, mobile: {...}, tv: {...} }
  onCalculate
}) {
  const handleChange = e => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // pricingData가 없으면 아무것도 렌더링하지 않음
  if (!pricingData) {
    return null;
  }

  // 총액 결합 전용 폼
  if (selected === 'total') {
    return (
      <div className="bg-white rounded-lg shadow p-4 mb-4">
        {/* 인터넷 요금제 단일 선택 */}
        <div className="mb-4">
          <label className="block mb-2 font-medium">인터넷 요금제 선택</label>
          <select
            name="internetPlan"
            value={formData.internetPlan}
            onChange={handleChange}
            className="w-full border rounded p-2"
          >
            <option value="">선택하세요</option>
            {Object.entries(pricingData.internet).map(([key, plan]) => (
              <option key={key} value={key}>
                {plan.name}
              </option>
            ))}
          </select>
        </div>

        {/* 모바일 요금제 최대 7회선 반복 선택 */}
        {[...Array(7)].map((_, idx) => (
          <div key={idx} className="mb-4">
            <label className="block mb-2 font-medium">
              모바일 요금제 회선 {idx + 1}
            </label>
            <select
              name={`mobilePlan${idx}`}
              value={formData[`mobilePlan${idx}`] || ''}
              onChange={handleChange}
              className="w-full border rounded p-2"
            >
              <option value="">선택하세요</option>
              {Object.entries(pricingData.mobile).map(([key, plan]) => (
                <option key={key} value={key}>
                  {plan.name}
                </option>
              ))}
            </select>
          </div>
        ))}

        {/* 계산하기 버튼 */}
        <button
          type="button"
          onClick={onCalculate}
          className="mt-4 w-full bg-blue-600 text-white py-3 rounded hover:bg-blue-700 transition"
        >
          계산하기
        </button>
      </div>
    );
  }

  // 그 외 일반 결합 폼
  return (
    <form className="bg-white rounded-lg shadow p-4 mb-4 grid grid-cols-1 md:grid-cols-3 gap-4">
      {/* 모바일 */}
      <div>
        <label className="block mb-2 font-medium">모바일 요금제</label>
        <select
          name="mobilePlan"
          value={formData.mobilePlan}
          onChange={handleChange}
          className="w-full border rounded p-2"
        >
          <option value="">선택하세요</option>
          {Object.entries(pricingData.mobile).map(([key, plan]) => (
            <option key={key} value={key}>
              {plan.name}
            </option>
          ))}
        </select>
      </div>

      {/* 인터넷 */}
      <div>
        <label className="block mb-2 font-medium">인터넷 요금제</label>
        <select
          name="internetPlan"
          value={formData.internetPlan}
          onChange={handleChange}
          className="w-full border rounded p-2"
        >
          <option value="">선택하세요</option>
          {Object.entries(pricingData.internet).map(([key, plan]) => (
            <option key={key} value={key}>
              {plan.name}
            </option>
          ))}
        </select>
      </div>

      {/* TV */}
      <div>
        <label className="block mb-2 font-medium">TV 요금제</label>
        <select
          name="tvPlan"
          value={formData.tvPlan}
          onChange={handleChange}
          className="w-full border rounded p-2"
        >
          <option value="">선택하세요</option>
          {Object.entries(pricingData.tv).map(([key, plan]) => (
            <option key={key} value={key}>
              {plan.name}
            </option>
          ))}
        </select>
      </div>

      {/* 계산하기 버튼 (폼 하단 전체 너비) */}
      <button
        type="button"
        onClick={onCalculate}
        className="mt-4 col-span-full bg-blue-600 text-white py-3 rounded hover:bg-blue-700 transition"
      >
        계산하기
      </button>
    </form>
  );
}
